/**
 * Typed `%…end` block renderers, the browser twins of the Block types in
 * `wrapper/internal/inputbuild/blocks.go`. Layout is a byte-for-byte
 * contract with the Go renderers: a job built here and the same job
 * generated by the CLI must be indistinguishable.
 */
import {
  SCAN_ATOM_COUNT,
  type MECPSettings,
  type ScanSettings,
  type TDDFTSettings,
  type ThermoSettings,
} from "./types";

/** `%name` + one indented line per entry + `end` (Go: blockText). */
function blockText(name: string, entries: string[]): string {
  return `%${name}\n${entries.map((e) => `  ${e}\n`).join("")}end`;
}

/**
 * Scan endpoints with at least two decimals but no trailing noise
 * (1.1 → "1.10", 109.471 → "109.471"), matching Go's trimFloat.
 */
export function trimFloat(v: number): string {
  let s = v.toFixed(6).replace(/0+$/, "");
  const dot = s.indexOf(".");
  while (s.length - dot - 1 < 2) s += "0";
  return s;
}

/** One `%geom Scan` entry line ("B 0 1 = 1.10, 1.80, 15"). */
export function renderScanDimension(scan: ScanSettings): string {
  return `${scan.coord} ${scan.atoms.join(" ")} = ${trimFloat(scan.from)}, ${trimFloat(scan.to)}, ${scan.steps}`;
}

/** The `%geom` block of a relaxed scan (Go: GeomBlock.Scans). */
export function renderGeomScanBlock(scan: ScanSettings): string {
  return blockText("geom", ["Scan", `  ${renderScanDimension(scan)}`, "end"]);
}

/** The `%tddft` block; "" without roots (Go: TDDFTBlock). */
export function renderTddftBlock(tddft: TDDFTSettings): string {
  if (tddft.nroots <= 0) return "";
  const entries = [`NRoots ${tddft.nroots}`];
  if (tddft.triplets) entries.push("Triplets true");
  return blockText("tddft", entries);
}

/** The `%mecp` block; "" without a second multiplicity (Go: MECPBlock). */
export function renderMecpBlock(mecp: MECPSettings): string {
  if (mecp.mult2 <= 0) return "";
  return blockText("mecp", [`Mult ${mecp.mult2}`]);
}

/**
 * The `%freq` thermochemistry conditions; unset (non-positive) fields
 * are omitted so ORCA's own defaults (298.15 K, 1 atm) stay ORCA's
 * (Go: FreqBlock).
 */
export function renderFreqBlock(thermo: ThermoSettings): string {
  const entries: string[] = [];
  if (thermo.temperatureK > 0) entries.push(`Temp ${trimFloat(thermo.temperatureK)}`);
  if (thermo.pressureAtm > 0) entries.push(`Pressure ${trimFloat(thermo.pressureAtm)}`);
  if (entries.length === 0) return "";
  return blockText("freq", entries);
}

/** Blocking problems with a scan request, before anything is rendered. */
export function scanProblems(scan: ScanSettings, atomCount: number): string[] {
  const out: string[] = [];
  const wanted = SCAN_ATOM_COUNT[scan.coord];
  const label = scan.coord === "B" ? "bond" : scan.coord === "A" ? "angle" : "dihedral";
  if (scan.atoms.length !== wanted) {
    out.push(`a ${label} scan drives ${wanted} atoms — ${scan.atoms.length} given`);
  }
  const seen = new Set<number>();
  for (const a of scan.atoms) {
    if (!Number.isInteger(a) || a < 0) {
      out.push(`scan atom index ${a} is not a valid 0-based index`);
    } else if (atomCount > 0 && a >= atomCount) {
      out.push(`scan atom index ${a} is out of range — the structure has ${atomCount} atoms (indices 0–${atomCount - 1})`);
    } else if (seen.has(a)) {
      out.push(`scan atom index ${a} is repeated — a ${label} needs distinct atoms`);
    }
    seen.add(a);
  }
  if (!(scan.steps >= 2)) out.push("a scan needs at least 2 points");
  if (scan.from === scan.to) out.push("scan range is empty — start and end are equal");
  return out;
}
